#include "../app/workspace.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
static int passed,failed;static wchar_t fixture[32768],file[32768];
#define CHECK(label,c) do{if(c){passed++;printf("ok %s\n",label);}else{failed++;printf("FAIL line %d: %s\n",__LINE__,label);}}while(0)
static session snapshot(const wchar_t *left,const wchar_t *right){session s;session_defaults(&s);s.ntabs[0]=s.ntabs[1]=1;s.tabs[0][0].path=_wcsdup(left);s.tabs[1][0].path=_wcsdup(right);s.ratio=.625;s.tree_w=288;s.active=1;return s;}
static void test_workspace_snapshot_validation_and_exact_paths(void){session s=snapshot(L"C:\\Work\\name ",L"\\\\wsl.localhost\\Ubuntu\\tmp\\a\uf03ab\xDC80");session copy;CHECK("workspace copies exact Windows and Linux UTF-16 paths",!workspace_clone(&s,&copy)&&!wcscmp(s.tabs[0][0].path,copy.tabs[0][0].path)&&!wcscmp(s.tabs[1][0].path,copy.tabs[1][0].path)&&copy.ratio==.625&&copy.active==1);copy.tabs[0][0].path[0]='D';CHECK("snapshot strings are independently owned",s.tabs[0][0].path[0]=='C');session_free(&copy);s.npins=1;s.pins[0]=_wcsdup(L"C:\\");CHECK("global pins cannot leak into workspace state",!workspace_snapshot_valid(&s));free(s.pins[0]);s.pins[0]=NULL;s.npins=0;s.cur[0]=1;CHECK("invalid active tab is rejected",!workspace_snapshot_valid(&s));s.cur[0]=0;s.ratio=0.0/0.0;CHECK("non-finite split is rejected",!workspace_snapshot_valid(&s));s.ratio=.5;wchar_t name[WS_NAME];CHECK("workspace names are labels with bounded valid Unicode",workspace_name(L"Development / main [A]",name)&&!workspace_name(L" bad",name)&&!workspace_name(L"bad\nname",name)&&!workspace_name(L"\xDC80",name));session_free(&s);}
static void test_workspace_envelope_and_corruption_rejection(void){workspace_catalog c={0},loaded={0};c.count=1;c.revision=9;wcscpy(c.items[0].name,L"Development");c.items[0].snapshot=snapshot(L"C:\\source",L"\\\\wsl.localhost\\Ubuntu\\tmp\\a\uf03ab\xDC80");uint8_t *data=NULL;size_t bytes=0;CHECK("catalog encodes reused exact session format",!workspace_format(&c,&data,&bytes)&&bytes>32);CHECK("catalog round-trips layout, names and raw paths",!workspace_parse(data,bytes,&loaded)&&loaded.revision==9&&loaded.count==1&&!wcscmp(loaded.items[0].snapshot.tabs[1][0].path,c.items[0].snapshot.tabs[1][0].path));data[bytes-1]^=1;CHECK("checksum failure retains previously loaded catalog",workspace_parse(data,bytes,&loaded)==ERROR_INVALID_DATA&&loaded.revision==9&&loaded.count==1);data[bytes-1]^=1;CHECK("truncation is refused",workspace_parse(data,bytes-1,&loaded)==ERROR_INVALID_DATA);data[0]^=1;CHECK("unknown envelope version is refused",workspace_parse(data,bytes,&loaded)==ERROR_INVALID_DATA);data[0]^=1;c.count=2;wcscpy(c.items[1].name,L"development");c.items[1].snapshot=snapshot(L"C:\\a",L"C:\\b");uint8_t *bad=NULL;size_t badbytes=0;CHECK("case-insensitive duplicate names cannot serialize",workspace_format(&c,&bad,&badbytes)==ERROR_INVALID_DATA&&!bad);free(data);workspace_free(&c);workspace_free(&loaded);}
static void test_workspace_explicit_mutations_and_revision_conflict(void){wchar_t temp[32768];GetTempPathW(32768,temp);swprintf(fixture,32768,L"%lsopenpilot-workspaces-%lu-%llu",temp,(unsigned long)GetCurrentProcessId(),(unsigned long long)GetTickCount64());CHECK("fresh owned workspace store",CreateDirectoryW(fixture,NULL));swprintf(file,32768,L"%ls\\session.ini.workspaces",fixture);workspace_catalog c={0},other={0};session s=snapshot(L"C:\\source",L"C:\\dest");CHECK("missing catalog loads empty",!workspace_load(file,&c,NULL)&&!c.count&&!c.revision);CHECK("explicit create persists workspace",!workspace_change(file,0,WS_CREATE,L"Dev",NULL,&s,&c,NULL)&&c.count==1&&c.revision==1);CHECK("second window loads current revision",!workspace_load(file,&other,NULL)&&other.revision==1);CHECK("duplicate Save as never overwrites",workspace_change(file,1,WS_CREATE,L"dev",NULL,&s,&c,NULL)==ERROR_ALREADY_EXISTS&&c.revision==1);s.ratio=.75;CHECK("explicit update replaces snapshot",!workspace_change(file,1,WS_UPDATE,L"Dev",NULL,&s,&c,NULL)&&c.revision==2&&c.items[0].snapshot.ratio==.75);CHECK("stale concurrent update is a conflict",workspace_change(file,other.revision,WS_UPDATE,L"Dev",NULL,&s,&other,NULL)==ERROR_REVISION_MISMATCH&&other.revision==1);CHECK("rename keeps tabs",!workspace_change(file,2,WS_RENAME,L"Dev",L"Development",NULL,&c,NULL)&&!wcscmp(c.items[0].name,L"Development")&&c.items[0].snapshot.ratio==.75);CHECK("delete persists empty catalog with new revision",!workspace_change(file,3,WS_DELETE,L"Development",NULL,NULL,&c,NULL)&&c.count==0&&c.revision==4);workspace_free(&c);workspace_free(&other);session_free(&s);}
static void test_workspace_cancel_lock_and_publish_failure_preserve_store(void){workspace_catalog c={0};session s=snapshot(L"C:\\a",L"C:\\b");CHECK("new item for failure probes",!workspace_change(file,4,WS_CREATE,L"Keep",NULL,&s,&c,NULL));uint64_t before=c.revision;HANDLE cancel=CreateEventW(NULL,TRUE,TRUE,NULL);CHECK("cancelled update preserves saved revision",workspace_change(file,before,WS_UPDATE,L"Keep",NULL,&s,&c,cancel)==ERROR_CANCELLED&&c.revision==before);CloseHandle(cancel);
 HANDLE held=CreateFileW(file,GENERIC_READ,FILE_SHARE_READ,NULL,OPEN_EXISTING,0,NULL);CHECK("private replacement-denied fixture",held!=INVALID_HANDLE_VALUE);CHECK("failed atomic replacement leaves prior snapshot intact",workspace_change(file,before,WS_RENAME,L"Keep",L"Lost",NULL,&c,NULL)!=0&&workspace_find(&c,L"Keep")==0&&c.revision==before);if(held!=INVALID_HANDLE_VALUE)CloseHandle(held);workspace_catalog reread={0};CHECK("disk still contains original after failed publication",!workspace_load(file,&reread,NULL)&&reread.revision==before&&workspace_find(&reread,L"Keep")==0);workspace_free(&reread);
 wchar_t lockpath[32768];swprintf(lockpath,32768,L"%ls.lock",file);held=CreateFileW(lockpath,GENERIC_READ|GENERIC_WRITE,0,NULL,CREATE_NEW,FILE_FLAG_DELETE_ON_CLOSE,NULL);CHECK("private lock contention fixture",held!=INVALID_HANDLE_VALUE);CHECK("busy store cannot be overwritten",workspace_change(file,before,WS_DELETE,L"Keep",NULL,NULL,&c,NULL)!=0&&c.count==1);if(held!=INVALID_HANDLE_VALUE)CloseHandle(held);workspace_free(&c);session_free(&s);
 HANDLE corrupt=CreateFileW(file,GENERIC_WRITE,0,NULL,TRUNCATE_EXISTING,0,NULL);DWORD wrote=0;if(corrupt!=INVALID_HANDLE_VALUE){WriteFile(corrupt,"broken",6,&wrote,NULL);CloseHandle(corrupt);}CHECK("invalid catalog is not replaced by a new Save as",workspace_change(file,0,WS_CREATE,L"Overwrite",NULL,NULL,&c,NULL)==ERROR_INVALID_DATA);DeleteFileW(file);RemoveDirectoryW(fixture);}
int wmain(void){test_workspace_snapshot_validation_and_exact_paths();test_workspace_envelope_and_corruption_rejection();test_workspace_explicit_mutations_and_revision_conflict();test_workspace_cancel_lock_and_publish_failure_preserve_store();printf("%d passed, %d failed; 4 workspace selectors\n",passed,failed);return failed?1:0;}
